    if (tab === "serp") return pendingOrganicCount ? `Classifique os ${pendingOrganicCount} resultado(s) restantes como Usar, Ignorar ou Não concorrente.` : "Todos os resultados orgânicos foram revisados; avance para Concorrentes.";
    if (tab === "concorrentes") return !analysis ? "Continue a investigação para registrar a curadoria." : !includedOrganicCount ? "Marque ao menos uma página comparável como Usar." : !analysis.payload.selectedCompetitorIds.length ? "Marque as páginas Usar que devem ser extraídas." : "A seleção foi confirmada; revise a composição da amostra.";
    if (tab === "estrutura-observada") return extractionFormats.partial || extractionFormats.comparable < 2 ? "Uma amostra editorial comparável ainda é insuficiente; formatos adicionais permanecem visíveis, mas fora da média." : "Revise a média, mediana, faixa e outliers da amostra comparável.";
    if (tab === "semantica-observada") return semanticSummary.navigation + semanticSummary.legal + semanticSummary.platform ? "Revise os termos marcados como possível ruído de navegação, legal ou plataforma; você pode recuperá-los." : "Sem ruído classificado pendente; retorne à curadoria quando quiser consolidar as evidências.";
